namespace MinecraftHost.Core;

/// <summary>How big a server folder's parts are, for the duplicate panel.</summary>
public sealed record ServerCopySize(long Total, long Worlds, long Map, int Files);

/// <summary>
/// Copies a whole server folder into a new one, for "Duplicate this server". Logs, crash reports and caches are left out;
/// the worlds and BlueMap's map data can be left out too (the copy then makes a new world / re-renders the map).
/// </summary>
public static class ServerCopy
{
    // regenerated by the server, or only about the original's past runs
    static readonly string[] LeftOutTop = { "logs", "crash-reports", "cache", ".cache", "debug", ".modpack-download", "safe-mode-plugins" };

    static bool IsWorld(string dir) => File.Exists(Path.Combine(dir, "level.dat"));
    static bool IsMap(string root, string dir) => Path.GetFileName(dir).Equals("bluemap", StringComparison.OrdinalIgnoreCase) && Path.GetDirectoryName(dir) == root;

    /// <summary>Every file that would be copied, and which part it belongs to.</summary>
    static IEnumerable<(string Path, bool World, bool Map)> Files(string root)
    {
        root = Path.GetFullPath(root).TrimEnd('\\');
        foreach (var file in Directory.EnumerateFiles(root))
            if (Keep(file)) yield return (file, false, false);
        foreach (var dir in Directory.EnumerateDirectories(root))
        {
            if (LeftOutTop.Contains(Path.GetFileName(dir), StringComparer.OrdinalIgnoreCase)) continue;
            var world = IsWorld(dir);
            var map = IsMap(root, dir);
            foreach (var file in Directory.EnumerateFiles(dir, "*", SearchOption.AllDirectories))
            {
                if (!Keep(file)) continue;
                // a world's datapacks count as settings: a copy without the worlds still gets them for its new world
                var inDatapacks = world && Path.GetRelativePath(dir, file).StartsWith("datapacks" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase);
                yield return (file, world && !inDatapacks, map);
            }
        }

        static bool Keep(string file)
        {
            var name = Path.GetFileName(file);
            return !name.Equals("session.lock", StringComparison.OrdinalIgnoreCase) && !name.EndsWith(".part", StringComparison.OrdinalIgnoreCase);
        }
    }

    public static ServerCopySize Measure(string root)
    {
        long total = 0, worlds = 0, map = 0; var count = 0;
        foreach (var (path, world, isMap) in Files(root))
        {
            long size;
            try { size = new FileInfo(path).Length; } catch { continue; }
            total += size; count++;
            if (world) worlds += size;
            if (isMap) map += size;
        }
        return new ServerCopySize(total, worlds, map, count);
    }

    /// <summary>Copies into <paramref name="to"/> (which must be new or empty), keeping each file's modified time.</summary>
    public static async Task CopyAsync(string from, string to, bool worlds, bool map, IProgress<TransferProgress> progress, CancellationToken ct)
    {
        from = Path.GetFullPath(from).TrimEnd('\\');
        var files = Files(from).Where(f => (worlds || !f.World) && (map || !f.Map)).Select(f => f.Path).ToList();
        long total = files.Sum(f => { try { return new FileInfo(f).Length; } catch { return 0L; } }), done = 0;
        var started = DateTime.Now;
        var buffer = new byte[1 << 20];
        var lastReport = DateTime.MinValue;
        Directory.CreateDirectory(to);
        foreach (var file in files)
        {
            ct.ThrowIfCancellationRequested();
            var target = Path.Combine(to, Path.GetRelativePath(from, file));
            Directory.CreateDirectory(Path.GetDirectoryName(target)!);
            await using (var src = new FileStream(file, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, 1 << 16, useAsync: true))
            await using (var dst = new FileStream(target, FileMode.Create, FileAccess.Write, FileShare.None, 1 << 16, useAsync: true))
            {
                int read;
                while ((read = await src.ReadAsync(buffer, ct)) > 0)
                {
                    await dst.WriteAsync(buffer.AsMemory(0, read), ct);
                    done += read;
                    if ((DateTime.Now - lastReport).TotalMilliseconds < 200) continue;
                    lastReport = DateTime.Now;
                    var fraction = total > 0 ? (double)done / total : 1;
                    var elapsed = (DateTime.Now - started).TotalSeconds;
                    var left = fraction > 0.02 && elapsed > 3 ? $"  ·  about {Math.Max(1, Math.Round(elapsed / fraction * (1 - fraction) / 60))} min left" : "";
                    progress.Report(new TransferProgress("Copying the server...", fraction, $"{done / 1048576.0:N0} MB of {total / 1048576.0:N0} MB{left}"));
                }
            }
            try { File.SetLastWriteTimeUtc(target, File.GetLastWriteTimeUtc(file)); } catch { }
        }
        progress.Report(new TransferProgress("Copying the server...", 1, $"{files.Count} files"));
    }
}
